changeSet.sql:

drop table if exists #cleanup;
create table #cleanup (AssetVersionUid uniqueidentifier, MaxUid uniqueidentifier, RemoveUid uniqueidentifier);
insert into #cleanup
	select	M.*,
			A.Uid as UidToRemove
	from	(
			select	AssetVersionUid,
					max(Uid) as MaxUid
			from	metrics.AssetVersionCondition
			group by AssetVersionUid
			having count(1) > 1
			) M
			inner join	(
						select		AssetVersionUid,
									Uid
						from		metrics.AssetVersionCondition 
						where		AssetVersionUid in (
										select	AssetVersionUid
										from	metrics.AssetVersionCondition
										group by AssetVersionUid
										having count(1) > 1
									)
						) A on A.AssetVersionUid = M.AssetVersionUid and Uid <> M.MaxUid;

update	T
set		T.AssetVersionConditionUid = S.MaxUid
from	metrics.AssetVersionConditionItem T
		inner join #cleanup S on S.Removeuid = T.AssetVersionConditionUid;

delete	metrics.AssetVersionCondition where Uid in (select RemoveUid from #cleanup);

IF NOT EXISTS (SELECT * FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA = 'metrics' AND TABLE_NAME = 'Score_Backup') BEGIN CREATE TABLE [metrics].[Score_Backup]( [AssetUid] [uniqueidentifier] NOT NULL, [EffectiveDate] [date] NOT NULL, [Value] [decimal](5, 3) NOT NULL, [RunDate] [datetime] NULL, [EndDate] [date] NULL, [ScoreType] [int] NOT NULL, [Uid] [uniqueidentifier] NOT NULL, [AllocationUid] [uniqueidentifier] NULL )
insert into [metrics].[Score_Backup] select * from [metrics].[Score] END GO
IF NOT EXISTS (SELECT * FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA = 'metrics' AND TABLE_NAME = 'ScoreItem_Backup') BEGIN CREATE TABLE [metrics].[ScoreItem_Backup]( [AssetUid] [uniqueidentifier] NOT NULL, [MetricAssetUid] [uniqueidentifier] NOT NULL, [EffectiveDate] [date] NOT NULL, [UpdatedOn] [datetime] NOT NULL, [Value] [bit] NOT NULL, [AdjustedWeight] [decimal](5, 3) NULL, [RunDate] [datetime] NULL, [EndDate] [date] NULL, [Uid] [uniqueidentifier] NOT NULL, [AssetVersionUid] [uniqueidentifier] NULL, [Evidence] [nvarchar](max) NULL, [ConditionUid] [uniqueidentifier] NULL, [AdjustedMaxWeight] [decimal](5, 3) NULL )
insert into [metrics].[ScoreItem_Backup] select * from [metrics].[ScoreItem] END GO
-- Rebuild group measure instances. Figure out which measure groups need to be added to score item table. delete metrics.ScoreItem where MetricAssetUid in (select Uid from metrics.Asset where IsGroup = 1);
drop table if exists #groupItems; select distinct G.Uid as GroupUid, I.AssetUid, I.EffectiveDate, I.EndDate, GV.EffectiveDate as GroupEffectiveDate, GV.[Weight] as RawWeight, cast(null as decimal(5,3)) as AdjustedWeight, cast(null as decimal(5,3)) as AdjustedMaxWeight into #groupItems from metrics.ScoreItem I inner join metrics.Asset A on A.Uid = I.MetricAssetUid inner join metrics.Asset G on G.Uid = A.ParentUid cross apply ( select max(EffectiveDate) as EffectiveDate from metrics.AssetVersion where AssetUid = G.Uid and EffectiveDate <= I.EffectiveDate ) GVD inner join metrics.AssetVersion GV on GV.AssetUid = G.Uid and GV.EffectiveDate = GVD.EffectiveDate;
alter table #groupItems add ScoreItemUid uniqueidentifier default(newid()) not null;
drop table if exists #rootItems; select distinct I.AssetUid, I.EffectiveDate, I.MetricAssetUid, IV.Weight as RawWeight, I.AdjustedWeight, I.AdjustedMaxWeight into #rootItems from metrics.ScoreItem I inner join metrics.Asset A on A.Uid = I.MetricAssetUid and A.ParentUid is null cross apply ( select max(EffectiveDate) as EffectiveDate from metrics.AssetVersion where AssetUid = A.Uid and EffectiveDate <= I.EffectiveDate ) IVD inner join metrics.AssetVersion IV on IV.AssetUid = A.Uid and IV.EffectiveDate = IVD.EffectiveDate;
update T set T.AdjustedMaxWeight = round(T.RawWeight / (T.RawWeight+Gt.Total+It.Total),3) --select *, round(T.RawWeight / (T.RawWeight+Gt.Total+It.Total),3) as PossibleAdjustedMaxWeight from #groupItems T cross apply ( select coalesce(sum(RawWeight),0) as Total from #groupItems where AssetUid = T.AssetUid and EffectiveDate = T.EffectiveDate and GroupUid <> T.GroupUid ) Gt cross apply ( select coalesce(sum(RawWeight),0) as Total from #rootItems where AssetUid = T.AssetUid and EffectiveDate = T.EffectiveDate ) It;
update T set T.AdjustedWeight = round(T.AdjustedMaxWeight * It.Total,3) -- select *, T.AdjustedMaxWeight * It.Total, from #groupItems T cross apply ( select coalesce(sum(case I.Value when 1 then I.AdjustedWeight else 0 end),0) as Total from metrics.ScoreItem I inner join metrics.Asset A on A.Uid = I.MetricAssetUid and A.ParentUid = T.GroupUid and I.AssetUid = T.AssetUid and I.EffectiveDate = T.EffectiveDate ) It;
alter table metrics.ScoreItem alter column Value bit null
declare @dt datetime = getutcdate()
INSERT INTO [metrics].[ScoreItem] ([Uid], [AssetUid], [MetricAssetUid], [EffectiveDate], [UpdatedOn], [AdjustedWeight], [RunDate], [EndDate], [AdjustedMaxWeight]) select ScoreItemUid, AssetUid, GroupUid, EffectiveDate, @dt, AdjustedWeight, @dt, EndDate, AdjustedMaxWeight from #groupItems;
-- Add constraint to Score table. if not exists (select * from [INFORMATION_SCHEMA].[TABLE_CONSTRAINTS] where CONSTRAINT_TYPE = 'UNIQUE' and CONSTRAINT_NAME = 'UQ_MetricScore') begin alter table [metrics].[Score] add constraint UQ_MetricScore unique clustered ( [AssetUid], [ScoreType], [EffectiveDate] ); end
-- Set allocationUid on score table update Sc set Sc.AllocationUid = Al.Uid from metrics.Score Sc inner join Asset A on A.Uid = Sc.AssetUid inner join AssetType T on T.ID = A.AssetTypeID inner join metrics.Allocation Al on Al.AssetTypeUid = T.Uid and Al.ScoreType = Sc.ScoreType;
-- Set versionUid on score item table update Si set Si.AssetVersionUid = V.Uid from metrics.ScoreItem Si cross apply ( select max(EffectiveDate) as EffectiveDate from metrics.AssetVersion where AssetUid = Si.MetricAssetUid and EffectiveDate <= Si.EffectiveDate ) Mx inner join metrics.AssetVersion V on V.AssetUid = Si.MetricAssetUid and V.EffectiveDate = Mx.EffectiveDate;
-- Set conditionUid on score item table update Si set Si.ConditionUid = C.Uid from metrics.ScoreItem Si cross apply ( select max(EffectiveDate) as EffectiveDate from metrics.AssetVersion where AssetUid = Si.MetricAssetUid and EffectiveDate <= Si.EffectiveDate ) Mx inner join metrics.AssetVersion V on V.AssetUid = Si.MetricAssetUid and V.EffectiveDate = Mx.EffectiveDate left join metrics.AssetVersionCondition C on C.AssetVersionUid = V.Uid;
-- Update non-group score items. update metrics.ScoreItem set AdjustedMaxWeight = AdjustedWeight where Uid not in (select ScoreItemUid from #groupItems); update metrics.ScoreItem set AdjustedWeight = case Value when 1 then AdjustedWeight else 0 end where Uid not in (select ScoreItemUid from #groupItems);
-- First, clear out the link table to prepare for reload. truncate table [metrics].[ScoreItemLink] GO
insert into [metrics].[ScoreItemLink] select S.Uid as ScoreUid, I.Uid as ScoreItemUid from metrics.Score S inner join metrics.ScoreItem I on I.AssetUid = S.AssetUid and ( (S.EffectiveDate between I.EffectiveDate and I.EndDate) or (S.EffectiveDate >= I.EffectiveDate and I.EndDate is null) ) order by S.AssetUid, S.EffectiveDate
ALTER TABLE [metrics].[Score] DROP CONSTRAINT [UQ_MetricScore] WITH ( ONLINE = OFF ) GO
alter table metrics.Score drop column ScoreType GO
delete metrics.Score where AllocationUid is null;
ALTER TABLE [metrics].[Score] alter column AllocationUid uniqueidentifier not null GO
ALTER TABLE [metrics].[Score] WITH CHECK ADD CONSTRAINT [FK_MetricScore_MetricAllocation] FOREIGN KEY([AllocationUid]) REFERENCES [metrics].[Allocation] ([Uid]) ON DELETE CASCADE ALTER TABLE [metrics].[Score] CHECK CONSTRAINT [FK_MetricScore_MetricAllocation] GO
CREATE CLUSTERED INDEX CIX_MetricScore ON metrics.Score (AssetUid asc, AllocationUid asc, EffectiveDate desc) GO
alter table [metrics].[ScoreItem] drop constraint [UQ_MetricScoreItem] alter table [metrics].[ScoreItem] drop column AssetUid alter table [metrics].[ScoreItem] drop column MetricAssetUid alter table [metrics].[ScoreItem] drop column EffectiveDate alter table [metrics].[ScoreItem] drop column EndDate GO
delete metrics.ScoreItem where AssetVersionUid is null;
ALTER TABLE [metrics].[ScoreItem] alter column AssetVersionUid uniqueidentifier not null GO
ALTER TABLE [metrics].[ScoreItem] WITH CHECK ADD CONSTRAINT [FK_MetricScoreItem_MetricAssetVersion] FOREIGN KEY(AssetVersionUid) REFERENCES [metrics].[AssetVersion] ([Uid]) ON DELETE NO ACTION ALTER TABLE [metrics].[ScoreItem] CHECK CONSTRAINT [FK_MetricScoreItem_MetricAssetVersion] GO
ALTER TABLE [metrics].[ScoreItem] WITH CHECK ADD CONSTRAINT [FK_MetricScoreItem_MetricAssetVersionCondition] FOREIGN KEY(ConditionUid) REFERENCES [metrics].[AssetVersionCondition] ([Uid]) ON DELETE NO ACTION ALTER TABLE [metrics].[ScoreItem] CHECK CONSTRAINT [FK_MetricScoreItem_MetricAssetVersionCondition] GO
ALTER TABLE [metrics].[ScoreItemLink] DROP CONSTRAINT [FK_MetricScoreItemLink_MetricScoreItem] GO
ALTER TABLE [metrics].[ScoreItem] DROP CONSTRAINT [PK_MetricScoreItem] GO
ALTER TABLE [metrics].[ScoreItem] ADD CONSTRAINT [PK_MetricScoreItem] PRIMARY KEY CLUSTERED ( [Uid] ASC ) GO
ALTER TABLE [metrics].[ScoreItemLink] WITH CHECK ADD CONSTRAINT [FK_MetricScoreItemLink_MetricScoreItem] FOREIGN KEY([ScoreItemUid]) REFERENCES [metrics].[ScoreItem] ([Uid]) ON DELETE CASCADE GO
ALTER TABLE [metrics].[ScoreItemLink] CHECK CONSTRAINT [FK_MetricScoreItemLink_MetricScoreItem] GO
